import axios from "axios";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "http://localhost:8080";

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    "Content-Type": "application/json",
  },
});

// Automatically attach JWT token
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("token");

    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    return config;
  },
  (error) => Promise.reject(error)
);

// ==================== ACCOUNT APIs ====================

export const fetchAccounts = () => {
  return api.get("/accounts");
};

export const fetchAccount = (id) => {
  return api.get(`/accounts/${id}`);
};

export const getAccountById = (id) => {
  return api.get(`/accounts/${id}`);
};

export const createAccount = (accountData) => {
  return api.post("/accounts", accountData);
};

// ==================== TRANSACTION APIs ====================

export const deposit = (data) => {
  return api.post("/transactions/deposit", data);
};

export const withdraw = (data) => {
  return api.post("/transactions/withdraw", data);
};

export const transfer = (data) => {
  return api.post("/transactions/transfer", data);
};

export const fetchTransactionHistory = (accountId) => {
  return api.get(`/transactions/account/${accountId}`);
};

export default api;
